-- =====================================================================

DROP FUNCTION IF EXISTS verificar_caso15(text);
DROP TABLE IF EXISTS rx_receita, rx_medicamento, rx_medico, rx_atendente CASCADE;

-- Atendentes da Farmácia Central: quem cadastra as receitas no sistema
CREATE TABLE rx_atendente (
  matricula  text PRIMARY KEY,  -- ex.: F-1102
  nome       text NOT NULL,
  turno      text,              -- 'manhã' (7h-13h), 'tarde' (13h-19h) ou 'noite' (19h-7h)
  admissao   date
);

-- Médicos do hospital, com o CRM do jeito oficial (só o número, já limpo)
CREATE TABLE rx_medico (
  id            integer PRIMARY KEY,
  nome          text NOT NULL,
  crm_numero    text,   -- número do CRM, ex.: '126845'. Registro provisório termina em -P, ex.: '45871-P'
  crm_uf        text,   -- estado do conselho, ex.: 'SP'
  especialidade text,
  registro      text,   -- 'definitivo' ou 'provisório'
  vinculo       text,   -- 'corpo clínico' ou 'residência médica'
  situacao      text,   -- 'ativo' ou 'aposentado'
  desligado_em  date    -- quando deixou o hospital (vazio se ainda trabalha)
);

-- Medicamentos que a farmácia avia
CREATE TABLE rx_medicamento (
  nome        text PRIMARY KEY,  -- ex.: 'Zolpidem 10 mg'
  classe      text,
  controlado  boolean,           -- true = exige receita de controle especial
  lista       text               -- lista da Portaria 344: 'A1', 'A2', 'A3', 'B1', 'C1' (vazio se não é controlado)
);

-- Receitas aviadas pela Farmácia Central, como foram DIGITADAS no sistema
CREATE TABLE rx_receita (
  id              integer PRIMARY KEY,
  cadastrada_em   timestamp,      -- quando a receita foi cadastrada no sistema
  cadastrada_por  text REFERENCES rx_atendente(matricula),
  paciente        text,
  medicamento     text REFERENCES rx_medicamento(nome),
  crm_texto       text,           -- o CRM do jeito que a atendente digitou (formatos variados!)
  texto_receita   text            -- a receita transcrita: partes separadas por ' | '
);






-- Conferir a resposta:  SELECT verificar_caso15('resposta');
CREATE FUNCTION verificar_caso15(resposta text) RETURNS text
LANGUAGE sql AS $$
  SELECT CASE md5(lower(trim(resposta)))
    WHEN '716428d7579b357c0cd222176b42ee96' THEN
      '🏆 CASO ENCERRADO! Gervásio cadastrava, de madrugada, receitas com o carimbo copiado de um médico aposentado e o mesmo erro de digitação em todas. A farmácia passou a validar o CRM contra o cadastro do hospital antes de aviar qualquer controlado. Parabéns, detetive!'
    ELSE
      '❌ Não é essa. Confira se escreveu exatamente como aparece nos dados e revise as pistas.'
  END
$$;

SELECT '✅ Caso 15 instalado! Volte para o guia e comece a Etapa 1.' AS status;
